select d.*, p.product_name
from pms_device d
left join pms_product p on p.product_id = d.product_id

    AND d.sn like concat('%', #{sn}, '%')
    AND d.device_code like concat('%', #{deviceCode}, '%')
    AND d.product_id = #{productId}
    AND d.online_status = #{onlineStatus}
    AND d.abnormal_flag = #{abnormalFlag}

order by d.device_id desc

