device_code = #{deviceCode}, product_id = #{productId}, shelf_no = #{shelfNo}, online_status = #{onlineStatus}, last_sync_time = #{lastSyncTime}, last_heartbeat = #{lastHeartbeat}, battery = #{battery}, firmware = #{firmware}, abnormal_flag = #{abnormalFlag}, abnormal_remark = #{abnormalRemark}, bind_time = #{bindTime}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
